<?php
namespace App\Controllers;
use App\Helpers\{View,Csrf,Flash,Auth,Setup}; use App\Services\AuthService; use App\Repositories\UserRepository; use App\Config\Database;
final class AuthController {
    public function loginForm():void{if(Auth::check()){header('Location: /dashboard');exit;}View::render('auth/login',['title'=>'Iniciar sesión']);}
    public function login():void{Csrf::validate();$s=new AuthService();$u=$s->authenticate(trim($_POST['username']??''),$_POST['password']??'');if(!$u){Flash::set('error','Usuario o contraseña incorrectos.');header('Location: /login');exit;}Auth::login((int)$u['id']);header('Location: /dashboard');exit;}
    public function registerForm():void{if(Auth::check()){header('Location: /dashboard');exit;}if(Setup::adminCount()===0){View::render('auth/setup-admin',['title'=>'Crear administrador inicial']);return;}View::render('auth/register',['title'=>'Crear cuenta de comprador']);}
    public function register():void{Csrf::validate();if(Setup::adminCount()===0){header('Location: /setup-admin');exit;}$d=$this->buyerData();$s=new AuthService();$e=$s->validateBuyerRegistration($d);if($e){$_SESSION['_old']=$d;$_SESSION['_errors']=$e;header('Location: /register');exit;}(new UserRepository())->create($d,'COMPRADOR');Flash::set('success','Cuenta de comprador creada. Ya puedes iniciar sesión.');header('Location: /login');exit;}
    public function setupForm():void{if(Setup::adminCount()>0){header('Location: /register');exit;}View::render('auth/setup-admin',['title'=>'Crear administrador inicial']);}
    public function setup():void{Csrf::validate(); if(!Setup::verifyKey($_POST['install_key']??'')){Flash::set('error','Código de instalación incorrecto.');header('Location: /setup-admin');exit;} $d=$this->data();$s=new AuthService();$e=$s->validateRegistration($d);if($e){$_SESSION['_old']=$d;$_SESSION['_errors']=$e;header('Location: /setup-admin');exit;} $pdo=Database::connection();$lock=(int)$pdo->query("SELECT GET_LOCK('pasteleria_first_admin',5)")->fetchColumn();if($lock!==1){Flash::set('error','No se pudo obtener el bloqueo de instalación. Intenta nuevamente.');header('Location: /setup-admin');exit;}$pdo->beginTransaction();try{$st=$pdo->query("SELECT setting_value FROM system_settings WHERE setting_key='setup_completed' FOR UPDATE");$completed=$st->fetchColumn()==='1';$admins=(int)$pdo->query("SELECT COUNT(*) FROM users u JOIN roles r ON r.id=u.role_id WHERE r.name='ADMIN'")->fetchColumn();if($completed||$admins>0){$pdo->rollBack();$pdo->query("SELECT RELEASE_LOCK('pasteleria_first_admin')");http_response_code(403);exit('La configuración inicial ya fue realizada.');}$id=(new UserRepository())->create($d,'ADMIN');$pdo->prepare("INSERT INTO system_settings(setting_key,setting_value) VALUES('setup_completed','1') ON DUPLICATE KEY UPDATE setting_value='1'")->execute();$pdo->commit();$pdo->query("SELECT RELEASE_LOCK('pasteleria_first_admin')");@unlink(Setup::installKeyPath());Auth::login($id);Flash::set('success','Administrador creado. La configuración inicial quedó bloqueada.');header('Location: /dashboard');}catch(\Throwable $x){if($pdo->inTransaction())$pdo->rollBack();$pdo->query("SELECT RELEASE_LOCK('pasteleria_first_admin')");throw $x;}}
    public function googleStart():void{$config=$this->googleConfig();$state=bin2hex(random_bytes(24));$_SESSION['google_oauth_state']=$state;$query=http_build_query(['client_id'=>$config['id'],'redirect_uri'=>$config['redirect'],'response_type'=>'code','scope'=>'openid email profile','state'=>$state,'prompt'=>'select_account','access_type'=>'online']);header('Location: https://accounts.google.com/o/oauth2/v2/auth?'.$query);exit;}
    public function googleCallback():void{if(!isset($_GET['state'],$_SESSION['google_oauth_state'])||!hash_equals($_SESSION['google_oauth_state'],(string)$_GET['state'])){unset($_SESSION['google_oauth_state']);Flash::set('error','La solicitud de Google venció o no es válida.');header('Location: /register');exit;}unset($_SESSION['google_oauth_state']);if(isset($_GET['error'])||empty($_GET['code'])){Flash::set('error','No se pudo completar el acceso con Google.');header('Location: /register');exit;}try{$config=$this->googleConfig();$token=$this->googleRequest('https://oauth2.googleapis.com/token',['code'=>(string)$_GET['code'],'client_id'=>$config['id'],'client_secret'=>$config['secret'],'redirect_uri'=>$config['redirect'],'grant_type'=>'authorization_code']);if(empty($token['access_token']))throw new \RuntimeException((string)($token['error_description']??'Google no entregó un token válido.'));$profile=$this->googleRequest('https://openidconnect.googleapis.com/v1/userinfo',null,(string)$token['access_token']);if(empty($profile['sub'])||empty($profile['email'])||empty($profile['email_verified']))throw new \RuntimeException('Google no devolvió un correo verificado.');$users=new UserRepository();$user=$users->findByGoogleSub((string)$profile['sub']);$id=$user?(int)$user['id']:$users->createGoogle($profile);Auth::login($id);Flash::set('success','Bienvenido. Iniciaste sesión con Google.');header('Location: /dashboard');exit;}catch(\Throwable $e){Flash::set('error','No fue posible iniciar con Google: '.$e->getMessage());header('Location: /register');exit;}}
    private function googleConfig():array{$id=(string)\App\Helpers\Env::get('GOOGLE_CLIENT_ID','');$secret=(string)\App\Helpers\Env::get('GOOGLE_CLIENT_SECRET','');if($id===''||$secret===''){Flash::set('error','Falta configurar GOOGLE_CLIENT_ID y GOOGLE_CLIENT_SECRET en .env.');header('Location: /register');exit;}$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$host=$_SERVER['HTTP_HOST']??'127.0.0.1:3000';return ['id'=>$id,'secret'=>$secret,'redirect'=>$scheme.'://'.$host.'/auth/google/callback'];}
    private function googleRequest(string $url,?array $form=null,?string $bearer=null):array{$headers=['Accept: application/json'];$options=['http'=>['method'=>$form===null?'GET':'POST','ignore_errors'=>true,'timeout'=>15]];if($form!==null){$headers[]='Content-Type: application/x-www-form-urlencoded';$options['http']['content']=http_build_query($form);}if($bearer!==null)$headers[]='Authorization: Bearer '.$bearer;$options['http']['header']=implode("\r\n",$headers);$raw=@file_get_contents($url,false,stream_context_create($options));if($raw===false)throw new \RuntimeException('No se pudo conectar con Google.');$data=json_decode($raw,true);if(!is_array($data))throw new \RuntimeException('Google devolvió una respuesta inválida.');return $data;}
    public function logout():void{Csrf::validate();Auth::logout();header('Location: /');exit;}
    private function data():array{$username=trim($_POST['username']??'');return ['first_name'=>trim($_POST['first_name']??''),'second_name'=>'','last_name'=>trim($_POST['last_name']??''),'second_last_name'=>'-','username'=>$username,'email'=>$username.'@admin.local','password'=>$_POST['password']??'','password_confirm'=>$_POST['password_confirm']??''];}
    private function buyerData():array{$username=trim($_POST['username']??'');return ['first_name'=>trim($_POST['first_name']??''),'second_name'=>'','last_name'=>trim($_POST['last_name']??''),'second_last_name'=>'','username'=>$username,'email'=>$username.'@comprador.local','password'=>$_POST['password']??'','password_confirm'=>$_POST['password_confirm']??''];}
}
